import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { vec2, uv, mix, smoothstep, uniform, time, Fn, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const group = new Group();

  // --- RESOLVE TEXT CONTENT ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const bodyItem = items.find(item => item.role === 'body' || item.text?.length > 20) || items[0];
  const bodyText = bodyItem?.text || '';
  const bodyFontSize = bodyItem?.typography?.fontSize || 31;

  // --- BUILD BACKDROP PLANE WITH ENGINEERED GRADIENT ---
  const geometry = new PlaneGeometry(4.5, 1.8);

  // Gradient material using TSL nodes - engineered gradient surface with subtle grain
  const gradientNode = Fn(() => {
    const vUv = uv();

    // Vertical gradient from surface (bottom) to accent tint (top)
    const gradPos = vUv.y;

    // Primary gradient: surface (#0b0b10) through paper-ish mid to accent hint
    const colorA = vec3(0.043, 0.043, 0.062); // surface
    const colorB = vec3(0.1, 0.1, 0.13); // slightly lighter
    const colorC = vec3(0.91, 0.925, 0.95); // paper hint
    const accentColor = vec3(1.0, 0.165, 0.22); // accent

    // Engineered gradient with multiple stops
    const t1 = smoothstep(0.0, 0.4, gradPos);
    const t2 = smoothstep(0.4, 0.7, gradPos);
    const t3 = smoothstep(0.7, 1.0, gradPos);

    let mixed = mix(colorA, colorB, t1);
    mixed = mix(mixed, colorC, t2);
    mixed = mix(mixed, accentColor, t3 * 0.12); // subtle accent hint at top

    // Subtle grain overlay (static - no interactivity)
    const grainSeed = vec2(vUv.x * 512, vUv.y * 320);
    const grain = clamp(mix(0.0, 1.0, grainSeed.x * 0.001 + grainSeed.y * 0.001), 0.0, 1.0);
    const grainAmount = 0.03;
    mixed = mix(mixed, vec3(1.0), grain * grainAmount);

    // Slight vignette at edges
    const vignette = 1.0 - smoothstep(0.8, 1.0, length(vUv * 2.0 - 1.0)) * 0.15;
    mixed = mixed * vignette;

    return vec3(mixed);
  });

  const material = new MeshBasicNodeMaterial();
  material.colorNode = gradientNode();
  material.transparent = true;
  material.opacity = 0.95;

  const backdrop = new Mesh(geometry, material);
  backdrop.position.set(0, 0, -0.01); // slight z offset behind text
  group.add(backdrop);

  // --- TEXT RENDERING ---
  if (bodyText) {
    const textMesh = ctx.fontAtlas.createText(bodyText, {
      fontSize: bodyFontSize,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 400,
      letterSpacingPx: 0.02 * bodyFontSize
    });

    textMesh.position.set(0, 0, 0.01);

    // Scale to fit within the backdrop
    const textScale = 0.005;
    textMesh.scale.set(textScale, textScale, textScale);

    group.add(textMesh);
  }

  // --- SCENE PLACEMENT ---
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
    group.rotation.set(
      config.scenePosition.rotation?.x || 0,
      config.scenePosition.rotation?.y || 0,
      config.scenePosition.rotation?.z || 0
    );
    group.scale.set(
      config.scenePosition.scale?.x || 1,
      config.scenePosition.scale?.y || 1,
      config.scenePosition.scale?.z || 1
    );
  }

  // --- NO CINEMATIC PRIMITIVES (none specified) ---

  // --- EVENT HANDLERS ---
  group.userData.handlers = {};

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // --- ATLAS REGION (metadata for adapter) ---
  group.userData.atlasRegion = {
    atlas: config.atlasRegion?.atlas || 0,
    x: config.atlasRegion?.x || 0,
    y: config.atlasRegion?.y || 0,
    width: config.atlasRegion?.width || 512,
    height: config.atlasRegion?.height || 320
  };

  return group;
}
